select job_title, case when salary >= 124000 then 'high' when salary >= 80000 then 'mid' else 'low' end as salary_bucket, sum(case when job_title = 'Engineer' then salary else 0 end) as engineer_salary, concat_ws(', ', sort_array(collect_set(job_title))) as job_title_values, sum(salary) as total_salary from employees group by job_title, case when salary >= 124000 then 'high' when salary >= 80000 then 'mid' else 'low' end having total_salary > 356000;
